import{_ as t,o as e,c as i,an as s}from"./chunks/framework.DwXkzB5Y.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"BiophysicalBehaviour.jl","text":"Behaviour as the control of heat and water budgets","tagline":"what an organism does about its body temperature, metabolic rate and water loss: where it goes, how it holds itself and what it does with its fur, blood and breath, by rules or by optimisation.","actions":[{"theme":"brand","text":"Get Started","link":"/get_started"},{"theme":"alt","text":"View on Github","link":"https://github.com/BiophysicalEcology/BiophysicalBehaviour.jl"},{"theme":"alt","text":"API Reference","link":"/api"}]},"features":[{"title":"🎛️ Behaviour as control","details":"The heat budget is the plant, body temperature the state, a threshold trait the setpoint, and <a class=\\"highlight-link\\">thermoregulation the controller</a>.","link":"/manual/control"},{"title":"🦎 Ectotherms","details":"Emerge, bask, change colour and posture, <a class=\\"highlight-link\\">seek shade, climb and retreat underground</a>, hour by hour through a microclimate.","link":"/manual/ectotherm"},{"title":"🐇 Endotherms","details":"Raise and flatten fur, uncurl, vasodilate, <a class=\\"highlight-link\\">let core temperature rise, pant and sweat</a>, in a fixed order until the heat budget balances.","link":"/manual/endotherm_rules"},{"title":"📉 Optimisation","details":"Or state the costs and let <a class=\\"highlight-link\\">IPOPT, with derivatives from Enzyme</a>, find the combination of responses.","link":"/manual/optimisation"},{"title":"🐕 Bodies of many parts","details":"A trunk, head and limbs with <a class=\\"highlight-link\\">their own physiology</a>, one core and one pair of lungs.","link":"/manual/multipart"},{"title":"🌡️ Thresholds are the traits","details":"Body temperature is a state. <a class=\\"highlight-link\\">The temperatures at which an animal acts</a> are its traits.","link":"/manual/states_traits"},{"title":"↔️ Gradients and control","details":"Heat flows down gradients of potential. Behaviour follows <a class=\\"highlight-link\\">gradients of information</a>, between a state and its target.","link":"/manual/gradients"},{"title":"📦 For NicheMapR users","details":"How the behaviour of <a class=\\"highlight-link\\">ectotherm, endoR and HomoTherm</a> maps onto this package.","link":"/manual/nichemapr"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),l={name:"index.md"};function o(h,a,n,r,c,d){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h2 id="How-to-install-BiophysicalBehaviour.jl?" tabindex="-1">How to install BiophysicalBehaviour.jl? <a class="header-anchor" href="#How-to-install-BiophysicalBehaviour.jl?" aria-label="Permalink to &quot;How to install BiophysicalBehaviour.jl? {#How-to-install-BiophysicalBehaviour.jl?}&quot;">​</a></h2><p>BiophysicalBehaviour.jl can be installed from the Julia REPL:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">julia</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/BiophysicalEcology/BiophysicalBehaviour.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="Manual" tabindex="-1">Manual <a class="header-anchor" href="#Manual" aria-label="Permalink to &quot;Manual {#Manual}&quot;">​</a></h2><p>BiophysicalBehaviour.jl computes what an organism does to regulate its body temperature. It takes the heat budget of <a href="https://github.com/BiophysicalEcology/HeatExchange.jl" target="_blank" rel="noreferrer">HeatExchange.jl</a> and wraps a controller around it: the organism changes its position, its posture or its physiology, the heat budget is solved again, and the result is compared with a target. The package could as well have been called BiophysicalControl.jl, see <a href="./manual/control">Behaviour as control</a>.</p><p>It is part of the <a href="https://github.com/BiophysicalEcology" target="_blank" rel="noreferrer">BiophysicalEcology</a> ecosystem for mechanistic niche modelling. The bodies come from <a href="https://github.com/BiophysicalEcology/BiophysicalGeometry.jl" target="_blank" rel="noreferrer">BiophysicalGeometry.jl</a>, the heat budgets from HeatExchange.jl, and the environments to choose between from <a href="https://github.com/BiophysicalEcology/Microclimate.jl" target="_blank" rel="noreferrer">Microclimate.jl</a>. See the <a href="./manual/introduction">Introduction</a> for the design of the package and <a href="./manual/nichemapr">For NicheMapR users</a> for its origin in <a href="https://github.com/mrke/NicheMapR" target="_blank" rel="noreferrer">NicheMapR</a>.</p>`,6)])])}const g=t(l,[["render",o]]);export{u as __pageData,g as default};
